from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8
#define A_GROUP_STRIDE (TM + 4)
#define A_NUM_GROUPS (BM / TM)
#define A_PADDED_BM (A_NUM_GROUPS * A_GROUP_STRIDE)

__device__ __forceinline__ void loadAGmem(const float* __restrict__ A,
                                           int N, int globalRowA, int c4A, int k0,
                                           float4 &valA) {
    int globalColA = k0 + c4A * 4;
    if (globalRowA < N && (globalColA + 3) < N) {
        valA = *reinterpret_cast<const float4*>(&A[(size_t)globalRowA * N + globalColA]);
    } else {
        valA.x = (globalRowA < N && globalColA     < N) ? A[(size_t)globalRowA * N + globalColA]     : 0.0f;
        valA.y = (globalRowA < N && globalColA + 1 < N) ? A[(size_t)globalRowA * N + globalColA + 1] : 0.0f;
        valA.z = (globalRowA < N && globalColA + 2 < N) ? A[(size_t)globalRowA * N + globalColA + 2] : 0.0f;
        valA.w = (globalRowA < N && globalColA + 3 < N) ? A[(size_t)globalRowA * N + globalColA + 3] : 0.0f;
    }
}
// Asynchronously copy a 16-byte chunk of B directly from global memory into
// shared memory using cp.async (Ampere+), bypassing the register file so the
// copy engine can proceed independently of, and overlap with, the compute
// instructions issued right after it is launched. Falls back to a
// synchronous predicated load for boundary tiles or on older architectures.
__device__ __forceinline__ void loadBAsync(const float* __restrict__ B,
                                            float* smemDst, int N,
                                            int globalColB, int rB, int k0) {
    int globalRowB = k0 + rB;
#if __CUDA_ARCH__ >= 800
    if (globalRowB < N && (globalColB + 3) < N) {
        const float* gptr = &B[(size_t)globalRowB * N + globalColB];
        unsigned smemAddr = static_cast<unsigned>(__cvta_generic_to_shared(smemDst));
        asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
                     :: "r"(smemAddr), "l"(gptr));
        return;
    }
#endif
    float4 v;
    v.x = (globalRowB < N && globalColB     < N) ? B[(size_t)globalRowB * N + globalColB]     : 0.0f;
    v.y = (globalRowB < N && globalColB + 1 < N) ? B[(size_t)globalRowB * N + globalColB + 1] : 0.0f;
    v.z = (globalRowB < N && globalColB + 2 < N) ? B[(size_t)globalRowB * N + globalColB + 2] : 0.0f;
    v.w = (globalRowB < N && globalColB + 3 < N) ? B[(size_t)globalRowB * N + globalColB + 3] : 0.0f;
    *reinterpret_cast<float4*>(smemDst) = v;
}
__device__ __forceinline__ void cpAsyncCommit() {
#if __CUDA_ARCH__ >= 800
    asm volatile("cp.async.commit_group;\n");
#endif
}
__device__ __forceinline__ void cpAsyncWaitAll() {
#if __CUDA_ARCH__ >= 800
    asm volatile("cp.async.wait_group 0;\n");
#endif
}
__global__ void __launch_bounds__(256, 2) sgemm_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int N) {
    // Double-buffered shared memory tiles enable software pipelining:
    // global memory loads for the next K-tile are issued and overlapped
    // with compute on the current tile, hiding global memory latency.
    __shared__ float As[3][BK][A_PADDED_BM];
    __shared__ float Bs[3][BK][BN];
    const int blockRow = blockIdx.y;
    const int blockCol = blockIdx.x;
    // Warp-level tiling: assign each warp a WMxWN sub-tile of the block's
    // BM x BN output tile. This groups shared-memory accesses within a warp
    // so that lanes reading the A/B tiles hit far fewer distinct addresses
    // per instruction (broadcast-friendly), significantly reducing shared
    // memory bank conflicts compared to a flat thread-index mapping.
    const int WARP_SIZE = 32;
    const int WARP_ROWS = 2;              // warps along BM
    const int WARP_COLS = 4;              // warps along BN (WARP_ROWS*WARP_COLS == numWarps)
    const int WM = BM / WARP_ROWS;        // 64
    const int WN = BN / WARP_COLS;        // 32
    const int warpId = threadIdx.x / WARP_SIZE;
    const int lane = threadIdx.x % WARP_SIZE;
    const int warpRow = warpId / WARP_COLS;
    const int warpCol = warpId % WARP_COLS;
    const int laneRow = lane / (WN / TN);   // 0..(WM/TM -1)
    const int laneCol = lane % (WN / TN);   // 0..(WN/TN -1)
    const int threadRow = warpRow * (WM / TM) + laneRow; // 0..(BM/TM -1)
    const int threadCol = warpCol * (WN / TN) + laneCol; // 0..(BN/TN -1)
    const int rowStart = blockRow * BM;
    const int colStart = blockCol * BN;
    float threadResults[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            threadResults[i][j] = 0.0f;
        }
    }
    const int tid = threadIdx.x;
    // Each thread loads exactly one float4 for A and one float4 for B per
    // K-tile (BM*BK/4 == BK*BN/4 == numThreads == 256).
    const int rA = tid / (BK / 4);
    const int c4A = tid % (BK / 4);
    const int rB = tid / (BN / 4);
    const int c4B = tid % (BN / 4);
    const int globalRowA = rowStart + rA;
    const int globalColB = colStart + c4B * 4;
    // Group-based padding for the A shared-memory tile: rows are stored in
    // groups of TM elements with extra padding so that the TM/8 sub-tile
    // rows accessed simultaneously by a warp map to distinct shared-memory
    // banks, eliminating the 2-way bank conflicts that otherwise occur
    // when BM (128) and TM (8) interact with the 32 shared-memory banks.
    const int groupA = rA / TM;
    const int offA = rA % TM;
    const int rAStorage = groupA * A_GROUP_STRIDE + offA;
    const int numTiles = (N + BK - 1) / BK;
    float4 valA0;
    loadAGmem(A, N, globalRowA, c4A, 0, valA0);
    As[0][c4A * 4 + 0][rAStorage] = valA0.x;
    As[0][c4A * 4 + 1][rAStorage] = valA0.y;
    As[0][c4A * 4 + 2][rAStorage] = valA0.z;
    As[0][c4A * 4 + 3][rAStorage] = valA0.w;
    loadBAsync(B, &Bs[0][rB][c4B * 4], N, globalColB, rB, 0);
    cpAsyncCommit();
    bool hasTile1 = numTiles > 1;
    if (hasTile1) {
        float4 valA1;
        loadAGmem(A, N, globalRowA, c4A, BK, valA1);
        As[1][c4A * 4 + 0][rAStorage] = valA1.x;
        As[1][c4A * 4 + 1][rAStorage] = valA1.y;
        As[1][c4A * 4 + 2][rAStorage] = valA1.z;
        As[1][c4A * 4 + 3][rAStorage] = valA1.w;
        loadBAsync(B, &Bs[1][rB][c4B * 4], N, globalColB, rB, BK);
        cpAsyncCommit();
    }
    cpAsyncWaitAll();
    __syncthreads();
    // 3-stage software pipeline: while computing on tile t, prefetch tile
    // (t+2) into the buffer that is guaranteed to be free (its previous
    // occupant, tile t-1, was fully consumed in the prior iteration).
    // This deepens the pipeline versus double buffering, giving the
    // global-memory loads more independent instructions to overlap with,
    // further hiding load latency behind compute.
    for (int t = 0; t < numTiles; t++) {
        int curBuf = t % 3;
        bool hasPrefetch = (t + 2) < numTiles;
        int nextBuf = (t + 2) % 3;
        float4 valA;
        if (hasPrefetch) {
            int k0 = (t + 2) * BK;
            loadAGmem(A, N, globalRowA, c4A, k0, valA);
            loadBAsync(B, &Bs[nextBuf][rB][c4B * 4], N, globalColB, rB, k0);
            cpAsyncCommit();
        }
        #pragma unroll
        for (int kk = 0; kk < BK; kk++) {
            float4 a0 = *reinterpret_cast<const float4*>(&As[curBuf][kk][threadRow * A_GROUP_STRIDE]);
            float4 a1 = *reinterpret_cast<const float4*>(&As[curBuf][kk][threadRow * A_GROUP_STRIDE + 4]);
            float4 b0 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][threadCol * TN]);
            float4 b1 = *reinterpret_cast<const float4*>(&Bs[curBuf][kk][threadCol * TN + 4]);
            float regA[TM] = {a0.x, a0.y, a0.z, a0.w, a1.x, a1.y, a1.z, a1.w};
            float regB[TN] = {b0.x, b0.y, b0.z, b0.w, b1.x, b1.y, b1.z, b1.w};
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    threadResults[i][j] += regA[i] * regB[j];
                }
            }
        }
        if (hasPrefetch) {
            As[nextBuf][c4A * 4 + 0][rAStorage] = valA.x;
            As[nextBuf][c4A * 4 + 1][rAStorage] = valA.y;
            As[nextBuf][c4A * 4 + 2][rAStorage] = valA.z;
            As[nextBuf][c4A * 4 + 3][rAStorage] = valA.w;
            cpAsyncWaitAll();
            __syncthreads();
        }
    }
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        int globalRow = rowStart + threadRow * TM + i;
        if (globalRow < N) {
            int globalCol0 = colStart + threadCol * TN;
            if (globalCol0 + 7 < N) {
                float4 c0 = make_float4(threadResults[i][0], threadResults[i][1], threadResults[i][2], threadResults[i][3]);
                float4 c1 = make_float4(threadResults[i][4], threadResults[i][5], threadResults[i][6], threadResults[i][7]);
                *reinterpret_cast<float4*>(&C[(size_t)globalRow * N + globalCol0]) = c0;
                *reinterpret_cast<float4*>(&C[(size_t)globalRow * N + globalCol0 + 4]) = c1;
            } else {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    int globalCol = globalCol0 + j;
                    if (globalCol < N) {
                        C[(size_t)globalRow * N + globalCol] = threadResults[i][j];
                    }
                }
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N, "A must be square");
    TORCH_CHECK(B.size(0) == N && B.size(1) == N, "B must be square with same N as A");

    auto C = torch::empty({N, N}, A.options());

    dim3 blockDim((BM / TM) * (BN / TN), 1, 1);
    dim3 gridDim((N + BN - 1) / BN, (N + BM - 1) / BM, 1);

    sgemm_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled CUDA kernel with shared memory and register blocking.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matmul.matmul_cuda(A, B)


N = 2048 * 2


def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]


def get_init_inputs():
    return []

